"""Trial prompts for the tengwa illustrations in the cover's new manner (Mucha + Russian book graphics).
usage: mk_prompts_mucha.py META.json TEMPLATE_DIR OUTDIR KEY [KEY ...]"""
import sys, json, os
import numpy as np
from PIL import Image

meta = {s.split('-', 1)[1]: (s, n) for s, n, *_ in json.load(open(sys.argv[1]))}
tdir, out = sys.argv[2], sys.argv[3]
os.makedirs(out, exist_ok=True)

# gloss, poem (for meaning), how the letter is formed, the filled background
L = {
'malta': ('золото', 'Тяжкое ты злато! / Пальцы жжёшь ты хладом, / Солнце затмеваешь, / Тёмной лестью баешь.',
          'Две замкнутые дуги буквы — два круглых тяжёлых золотых слитка-каравая, стоящих рядом; нижняя черта — плоский золотой брусок, на котором они лежат. Золото холодно блестит.',
          'За слитками — большой круглый орнаментальный диск в манере Мухи, но это ЗАТМЕННОЕ СОЛНЦЕ: тёмный диск с тонким холодным золотым венцом, — «солнце затмеваешь». Вокруг — сокровищница в глубине пещеры: груды монет, кубки, цепи и самоцветы уходят в полумрак, по краям — тяжёлые каменные своды с вырезанным растительным орнаментом. Свет — холодный, металлический; палитра — старое золото, тёмный сине-зелёный, сумеречный индиго, немного винного.'),
'ore': ('сердце', 'В сомнениях или / В ужасных страданьях, / Прислушайся к сердцу — / Исчезнут метанья.',
        'Эльф (юноша с длинными светлыми волосами, в длинном вышитом одеянии) стоит, слегка склонив голову и закрыв глаза; контур его плеча и согнутой руки повторяет дугу буквы: плечо — верх дуги, рука опускается и загибается обратно к груди, ладонь прижата к сердцу — как на приложенной текущей версии.',
        'За головой и плечами — большой круглый орнаментальный диск-нимб в манере Мухи, с концентрическим узором из стилизованных сердцевидных листьев и звёзд. Вокруг диска — сумеречный сад: ветви с цветами, спускающиеся сверху текучими линиями, вдали — тёмные кипарисы и вечернее небо. Спокойствие после смятения: мягкий тёплый свет на лице и руке.'),
'numen': ('запад', 'Волны западного моря / Вновь и вновь, не зная горя, / Преклоняясь непорочно, / Привечают брег песочный.',
          'Две дуги буквы — два гребня высоких волн, закрученных пенными завитками, бегущих к берегу; волны крупные и орнаментальные, как в японской гравюре, переложенной на модерн.',
          'За волнами — большой круглый диск ЗАХОДЯЩЕГО СОЛНЦА на западе, решённый как орнаментальный диск Мухи: концентрические кольца тёплого золота, охры и пыльно-розового. Небо вокруг — сумеречный индиго и сине-зелёный с орнаментальными облаками-завитками; внизу — песчаный берег с раковинами, по краям — стебли морской травы, поднимающиеся текучими линиями.'),
}

HEAD = '''Нарисуй квадратную книжную иллюстрацию 1:1 для азбуки эльфийского письма тенгвар. Буква — {NAME} («{GLOSS}»). Стихотворение к букве (для смысла, НЕ писать на картинке): «{POEM}»
Приложены три картинки:
1) {SLUG}-template.png — ШАБЛОН ФОРМЫ: серый силуэт буквы. Главное требование: предметы на иллюстрации вместе образуют именно этот силуэт — в том же месте, того же размера и с теми же пропорциями (буква занимает от {X0}% до {X1}% ширины и от {Y0}% до {Y1}% высоты). Буква должна читаться с первого взгляда, ясно выделяясь на фоне.
2) {SLUG}-current.png — текущая версия этой иллюстрации: из неё бери СЮЖЕТ и то, как предметы образуют букву, но НЕ манеру, НЕ цвета и НЕ фон.
3) style-cover.png — обложка этой книги: повтори её МАНЕРУ и ПАЛИТРУ в точности.

КАК ПРЕДМЕТЫ ОБРАЗУЮТ БУКВУ: {SUBJ}

ФОН — ЗАПОЛНЕННЫЙ, без пустых однотонных участков: {BG}

СТИЛЬ (как на style-cover.png): европейский декоративный модерн рубежа XIX–XX веков в манере Альфонса Мухи — круглый орнаментальный диск, текучие линии волос, тканей и растений, «удар бича», концентрические узоры, — соединённый с русской книжной графикой эпохи модерна: уверенный тёмно-коричневый контур одинаковой толщины, плоские декоративные заливки, минимум градиентов, ясные мелкие орнаменты. Матовая фактура старой цветной литографии. Палитра обложки: старое золото, охра, шалфейно-зелёный, сумеречный индиго, сине-зелёный, слоновая кость, жемчужное серебро, немного пыльно-розового и тёмного винного. Не фотореализм, не 3D, не аниме, не современная цифровая живопись.

РАМКА: узкая золотая рамка с тёмно-коричневым контуром и небольшими растительными уголками в духе обложки; отступ около 3% от края. Фон доходит до рамки.

ВАЖНО: никаких надписей, букв (кроме той, которую образуют предметы), цифр, подписей и псевдотекста. Ничего лишнего.
'''

for key in sys.argv[4:]:
    slug, name = meta[key]
    gloss, poem, subj, bg = L[key]
    a = np.asarray(Image.open(os.path.join(tdir, slug + '-template.png')).convert('L')) < 230
    ys, xs = np.nonzero(a)
    txt = HEAD.format(NAME=name, GLOSS=gloss, POEM=poem, SLUG=slug, SUBJ=subj, BG=bg,
                      X0=xs.min() * 100 // 1024, X1=xs.max() * 100 // 1024, Y0=ys.min() * 100 // 1024, Y1=ys.max() * 100 // 1024)
    open(os.path.join(out, slug + '-prompt.txt'), 'w', encoding='utf-8').write(txt)
    print(slug)
